        {ADMIN_TABS.map(({ id, label }) => (
          <button
            key={id}
            type="button"
            role="tab"
            id={`admin-tab-${id}`}
            aria-selected={tab === id}
            aria-controls={`admin-panel-${id}`}
            tabIndex={tab === id ? 0 : -1}
            className={tab === id ? 'admin-tab admin-tab--active' : 'admin-tab'}
            onClick={() => setTab(id)}
          >
            {label}
          </button>
        ))}
      </nav>
    </div>

    <div
      className="admin-tab-panel"
      role="tabpanel"
      id={`admin-panel-${tab}`}
      aria-labelledby={`admin-tab-${tab}`}
